events.onValueChange:
function(form) {
  if (form.get('Have you been taking your medication every day this month?').getValue() === 'Yes') {
    form.get('If yes, which health facility are you receiving treatment from?').setHidden(false);
  } else {
    form.get('If yes, which health facility are you receiving treatment from?').setHidden(true);
  }

  if (form.get('Have you been taking your medication every day this month?').getValue() === 'No') {
    form.get('If No please specify why?').setHidden(false);
  } else {
    form.get('If No please specify why?').setHidden(true);
  }


}

function(form) {
  if (form.get('If yes, where are you taking your treatment/medicines from?').getValue() === 'Other (Please specify)') {
